import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.DMtjdCb-.js";const o="/help/assets/first-login.en.DkWDMIqw.png",r="/help/assets/connections.en.CrwD4TwH.png",i="/help/assets/connect-ani-rss.en.CpaiET6v.png",f=JSON.parse('{"title":"3. First login","description":"","frontmatter":{},"headers":[],"relativePath":"en/first-use.md","filePath":"en/first-use.md"}'),c={name:"en/first-use.md"};function l(d,e,p,h,g,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-first-login" tabindex="-1">3. First login <a class="header-anchor" href="#_3-first-login" aria-label="Permalink to &quot;3. First login&quot;">​</a></h1><p>Sign in, check that titles are available, and confirm where your media will be stored.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><ol><li>Open the AnimeMachine address shown in the startup window or container log.</li><li>Enter the initial username and random password from that window, then choose <strong>Sign in</strong>.</li><li>Keep the account details. The desktop package also saves them in <code>data/state/auth/initial-admin.txt</code>.</li></ol><p><img src="'+o+'" alt="Sign in with the account from the startup window or container log" loading="lazy"></p><p>Create additional accounts in <strong>Settings → Users</strong>. Viewing records and hidden titles are saved per account, so each household member can keep separate records.</p><p>Every account can change its own password. Administrators use <strong>Settings → Users → Change password</strong>; other accounts open <strong>Settings</strong>. Enter the current password and the new password twice. This device stays signed in; use the new password on other devices. Changing the initial password also removes its old saved credential file.</p><h2 id="let-the-catalog-prepare" tabindex="-1">Let the catalog prepare <a class="header-anchor" href="#let-the-catalog-prepare" aria-label="Permalink to &quot;Let the catalog prepare&quot;">​</a></h2><p>The first start downloads and verifies Bangumi Archive, prepares current and recent titles, then fills the remaining catalog in the background. The home-page status shows the current step. Bundled seasonal covers appear when their titles are ready.</p><p>Start browsing, subscribing, and playing as titles become available. Historical titles, library organization, and local download plans become available after the complete catalog is ready. If you stop, starting from the same folder resumes preparation.</p><p><strong>Expected result:</strong> title cards appear and open into details. You can use available titles while remaining covers are prepared.</p><h2 id="check-connections" tabindex="-1">Check connections <a class="header-anchor" href="#check-connections" aria-label="Permalink to &quot;Check connections&quot;">​</a></h2><p>Open <strong>Settings → Connections</strong> and check Ani-RSS and qBittorrent.</p><p><img src="'+r+'" alt="Full-stack connections: confirm the services are ready" loading="lazy"></p><p><img src="'+i+'" alt="Ani-RSS: automatically configured connection and media folder" loading="lazy"></p><ul><li><strong>Default NAS stack:</strong> wait for automatic setup; keys are filled automatically.</li><li><strong>Desktop or existing services:</strong> enter each service address and credentials, test the connection, then save.</li><li><strong>Existing media only:</strong> <a href="./collections.html">add your collection</a>; connect download services when needed.</li></ul><p>Fields marked <strong>Deployment</strong> come from startup settings and show their effective values. Keep them as supplied in the default stack. To connect your own services, set their addresses in the corresponding deployment template.</p><p>Your browser opens management pages at <code>http://NAS-address:port</code>. Inside the default stack, <code>http://ani-rss:7789</code> and <code>http://qbittorrent:8080</code> are the addresses used between containers.</p><h2 id="confirm-storage" tabindex="-1">Confirm storage <a class="header-anchor" href="#confirm-storage" aria-label="Permalink to &quot;Confirm storage&quot;">​</a></h2><p>The default stack already maps <code>/Library</code> and <code>/Media</code>; keep those defaults to start. To use another disk folder, check the NAS-to-container mapping in <a href="./collections.html">Existing collections</a> first.</p><p>Next, <a href="./subscribe.html">subscribe to one title</a> and complete a download.</p>',21)])])}const w=t(c,[["render",l]]);export{f as __pageData,w as default};
